<div class="auth-wrap"><form class="auth-card stack" method="post" action="<?= e(url('/register')) ?>"><?= csrf_field() ?><img class="brand-mini" src="<?= e(asset('brand/logo-mark.png')) ?>" alt=""><h1><?= e(__('auth.register')) ?></h1><?php foreach (errors() as $message): ?><p class="form-error"><?= e((string) $message) ?></p><?php endforeach; ?><label><?= e(__('fields.name')) ?><input name="name" value="<?= e((string) old('name')) ?>" required></label><label><?= e(__('fields.email')) ?><input type="email" name="email" value="<?= e((string) old('email')) ?>" required></label><label><?= e(__('fields.phone')) ?><input name="phone" value="<?= e((string) old('phone')) ?>"></label><label><?= e(__('fields.password')) ?><input type="password" name="password" required minlength="8"></label><label><?= e(__('fields.password_confirmation')) ?><input type="password" name="password_confirmation" required minlength="8"></label><button class="btn btn-primary" type="submit"><?= e(__('auth.register')) ?></button><a href="<?= e(url('/login')) ?>"><?= e(__('auth.have_account')) ?></a></form></div>
